n><section class="dashboard-card"><h2 class="mb-4 font-bold text-slate-950">Suggested Questions</h2><div class="space-y-2">@foreach($suggestedQuestions as $suggestion)<button type="button" x-on:click="question = @js($suggestion); submit()" class="flex w-full items-center gap-2 rounded-lg border border-slate-100 bg-slate-50 px-3 py-2.5 text-left text-[11px] font-semibold text-slate-600 hover:border-violet-200 hover:bg-violet-50 hover:text-violet-700"><i data-lucide="sparkles" class="size-3.5 shrink-0 text-violet-500"></i><span>{{ $suggestion }}</span></button>@endforeach</div><button type="button" class="mt-3 w-full text-center text-xs font-bold text-violet-600 hover:text-violet-800">View all suggestions <i data-lucide="arrow-right" class="inline size-3.5"></i></button></section></aside>

            <aside class="space-y-5"><section class="dashboard-card"><div class="mb-4 flex items-center justify-between"><h2 class="font-bold text-slate-950">Recent Conversations</h2><button type="button" class="text-xs font-bold text-violet-600 hover:text-violet-800">View all</button></div><div class="space-y-2">@foreach($suggestedQuestions as $suggestion)<button type="button" x-on:click="question = @js($suggestion); submit()" class="group flex w-full items-start gap-2 rounded-lg border border-slate-100 p-3 text-left hover:border-violet-200 hover:bg-violet-50"><i data-lucide="chevron-right" class="mt-0.5 size-3.5 shrink-0 text-slate-400 group-hover:text-violet-600"></i><span class="text-xs font-semibold leading-5 text-slate-600 group-hover:text-violet-800">{{ $suggestion }}<small class="mt-1 block text-[10px] font-normal text-slate-400">Suggested query</small></span></button>@endforeach</div></section><section class="overflow-hidden rounded-xl border border-violet-100 bg-gradient-to-br from-violet-50 to-white p-5"><div class="flex items-center gap-2 text-violet-800"><i data-lucide="sparkles" class="size-4"></i><h2 class="font-bold">AI Copilot Tips</h2></div><p class="mt-3 text-xs leading-5 text-slate-600">Ask questions in natural language. The Copilot will securely query your data and provide accurate, permission-aware insights.</p><a href="#ask" class="mt-4 inline-flex items-center gap-1 text-xs font-bold text-violet-600 hover:text-violet-800">Ask a question <i data-lucide="arrow-right" class="size-3.5"></i></a></section></aside>
