    @push('scripts')<script>function copilotChat(){return{question:'',loading:false,messages:@js($activeConversation['messages'] ?? []),conversations:@js($conversations),conversationId:@js($activeConversation['id'] ?? null),clearConversation(){this.messages=[];this.conversationId=null},loadConversation(conversation){this.conversationId=conversation.id;this.messages=conversation.messages||[];this.$nextTick(()=>this.$refs.messages.scrollTop=this.$refs.messages.scrollHeight)},time(){return new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})},submit(){if(!this.question.trim()||this.loading)return;const q=this.question.trim();this.messages.push({id:Date.now(),role:'user',text:q,time:this.time()});this.question='';this.loading=true;fetch('{{ route('ai-copilot.ask') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content,'Accept':'text/html'},body:JSON.stringify({question:q,conversation_id:this.conversationId})}).then(r=>r.text()).then(html=>{const t=document.createElement('div');t.innerHTML=html;const answer=t.querySelector('[data-copilot-answer]');if(answer?.dataset.conversationId)this.conversationId=Number(answer.dataset.conversationId);this.messages.push({id:Date.now()+1,role:'assistant',html:answer?answer.querySelector('.copilot-markdown')?.innerHTML:'<p>The Copilot returned an empty answer.</p>',time:this.time()});const saved=this.conversations.find(conversation=>conversation.id===this.conversationId);if(saved){saved.messages=this.messages;saved.updated='Just now'}else{this.conversations.unshift({id:this.conversationId,title:q,updated:'Just now',messages:this.messages})}}).catch(()=>this.messages.push({id:Date.now()+1,role:'assistant',html:'<p>The Copilot could not complete this request. Please check the provider settings and try again.</p>',time:this.time()})).finally(()=>{this.loading=false;this.$nextTick(()=>this.$refs.messages.scrollTop=this.$refs.messages.scrollHeight)})}}}</script>@endpush
